source("h.R")
E <- function(s, f) D$engine_write(s$engine, f, timeout = 5)
db <- function(s, n) D$engine_db(s$engine, n)
cat("pop file: default, shared, in transact\n")
s <- newc(); f <- tempfile(fileext = ".txt"); writeLines("hello", f)
cache_set(s, "f", f, codec = codec_file()); print(try_(cache_pop(s, "f", "DEFAULT"))); print(cache_has(s, "f"))
cache_set(s, "f", f, codec = codec_file()); cache_set(s, "g", f, codec = codec_file()); p <- try_(cache_pop(s, "f")); print(class(p)); print(file.exists(p))
cache_delete(s, "g"); cache_set(s, "f", f, codec = codec_file()); p <- cache_transact(s, { p <- cache_pop(s, "f"); cat("inside exists:", file.exists(p), "\n"); p }); print(file.exists(p))
cat("user codec: inline decode, lazy path, NULL value, meta\n")
lines <- codec("lines", encode = function(value, path) { writeLines(value, path); list(n = length(value)) }, decode = function(path, meta) { x <- readLines(path); stopifnot(length(x) == meta$n); x }, ext = "txt")
pathc <- codec("pathc", encode = function(value, path) writeLines(value, path), decode = function(path, meta) path)
nullc <- codec("nullc", encode = function(value, path) writeBin(raw(3), path), decode = function(path, meta) NULL)
s <- newc(inline_max = 100, codecs = list(lines, pathc, nullc))
cache_set(s, "l_small", c("a","b"), codec = lines); cache_set(s, "l_big", rep("abcdefghij", 20), codec = lines)
print(cache_get(s, "l_small")); print(length(cache_get(s, "l_big"))); print(basename(cache_path(s, "l_big"))); print(tmpf(s))
cache_set(s, "p_small", "x", codec = pathc); p <- cache_get(s, "p_small"); cat("inline user codec returning path: exists =", file.exists(p), "\n")
cache_set(s, "null_i", 1, codec = nullc); print(try_(cache_get(s, "null_i"))); print(try_(cache_get(s, "null_i", "DEF"))); print(cache_mget(s, c("null_i", "l_small")))
s2 <- newc(inline_max = 0, codecs = list(nullc)); cache_set(s2, "null_b", 1, codec = nullc); print(try_(cache_get(s2, "null_b"))); print(try_(cache_pop(s2, "null_b")))
cat("readonly handle\n")
d <- cache_dir(s); cache_close(s)
r <- cache(d, readonly = TRUE, codecs = list(lines)); print(cache_get(r, "l_small")); print(length(cache_get(r, "l_big"))); print(try_(cache_get(r, "p_small"))); print(nrow(cache_check(r, hash = TRUE))); print(try_(cache_check(r, repair = TRUE))); print(tmpf(r)); cache_close(r)
cat("unknown codec / newer version\n")
r <- cache(d); print(try_(cache_get(r, "l_small"))); print(try_(cache_pop(r, "l_small"))); print(cache_has(r, "l_small"))
lines2 <- codec("lines", encode = lines$encode, decode = lines$decode, version = 2); cache_close(r)
r <- cache(d, codecs = list(lines2)); cache_set(r, "v2", "z", codec = lines2); cache_close(r)
r <- cache(d, codecs = list(lines)); print(try_(cache_get(r, "v2"))); print(cache_get(r, "l_small"))
cat("per-call codec with the same name as registered but different object\n")
lines_b <- codec("lines", encode = function(value, path) writeLines(rev(value), path), decode = function(path, meta) "OTHER")
cache_set(r, "lb", c("1","2"), codec = lines_b); print(cache_get(r, "lb"))
cat("compress default persisted?\n")
dd <- tempfile(); s <- cache(dd, codec = codec_rds(compress = TRUE), inline_max = 10); cache_set(s, "a", rep(1L, 1e4)); print(cache_info(s, "a")$bytes); cache_close(s)
s <- cache(dd); cache_set(s, "b", rep(1L, 1e4)); print(cache_info(s, "b")$bytes); print(identical(cache_get(s, "a"), cache_get(s, "b")))
cat("cache_path cases\n")
s <- newc(inline_max = 10); cache_set(s, "x", raw(50), expire = -1); print(try_(cache_path(s, "x"))); print(try_(cache_path(s, "nope")))
lk <- strrep("k", 600); cache_set(s, lk, raw(50)); print(file.exists(cache_path(s, lk))); print(cache_entries(s)$bytes); print(nrow(cache_check(s, hash=TRUE)))
